import { useState } from 'react';
import { Link } from 'react-router-dom';
import styles from '../styles/RegisterPage.module.css';
import learnImg from '../assets/learnImage.png';

function RegisterPage() {
  const [darkMode, setDarkMode] = useState(false);
  const [formData, setFormData] = useState({
    fullname: '',
    username: '',
    password: '',
    confirmPassword: '',
    dob: '',
    level: '',
    terms: false,
  });
  const [message, setMessage] = useState({ text: '', type: '' });

  const toggleTheme = () => setDarkMode(prev => !prev);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value,
    });
  };

  const validatePassword = (password) => {
    // Minimum 8 characters, uppercase, lowercase, number, special character
    const regex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
    return regex.test(password);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setMessage({ text: '', type: '' });

    // Check for empty fields
    for (const key in formData) {
      if ((formData[key] === '' || formData[key] === false) && key !== 'terms') {
        setMessage({ text: 'Please complete all fields.', type: 'error' });
        return;
      }
    }

    // Terms checkbox
    if (!formData.terms) {
      setMessage({ text: 'You must agree to the terms.', type: 'error' });
      return;
    }

    // Password strength
    if (!validatePassword(formData.password)) {
      setMessage({ text: 'Password must be at least 8 characters and include uppercase, lowercase, number, and special character.', type: 'error' });
      return;
    }

    // Password match
    if (formData.password !== formData.confirmPassword) {
      setMessage({ text: 'Passwords do not match.', type: 'error' });
      return;
    }

    // Simulate account creation (replace with backend API)
    const existingAccounts = ['user1', 'user2']; // mock
    if (existingAccounts.includes(formData.username)) {
      setMessage({ text: 'Username already exists.', type: 'error' });
      return;
    }

    setMessage({ text: 'Account successfully created!', type: 'success' });

    // Reset form
    setFormData({
      fullname: '',
      username: '',
      password: '',
      confirmPassword: '',
      dob: '',
      level: '',
      terms: false,
    });
  };

  return (
    <div className={darkMode ? styles['dark-mode'] : ''}>
      <header className={styles.header}>
        <h1>Registration</h1>
        <nav>
          <ul className={styles.navList}>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact">Contact</Link></li>
            <li><Link to="/register" className={styles.active}>Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className={styles.themeToggle} onClick={toggleTheme}>
        Toggle Dark/Light
      </button>

      {/* Card container */}
      <section className={styles.registerCard}>
        <h2>Sign Up Form</h2>
        <img src={learnImg} alt="Learning" width="200" style={{ display: 'block', margin: '15px auto', borderRadius: '10px' }} />

        <form onSubmit={handleSubmit} className={styles.registerForm}>
          <label>Full Name</label>
          <input type="text" name="fullname" value={formData.fullname} onChange={handleChange} required />

          <label>Preferred Username</label>
          <input type="text" name="username" value={formData.username} onChange={handleChange} required />

          <label>Password</label>
          <input type="password" name="password" value={formData.password} onChange={handleChange} required />

          <label>Confirm Password</label>
          <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} required />

          <label>Date of Birth</label>
          <input type="date" name="dob" value={formData.dob} onChange={handleChange} required />

          <label>Interest Level</label>
          <div>
            <label><input type="radio" name="level" value="Beginner" checked={formData.level === 'Beginner'} onChange={handleChange} /> Beginner</label>
            <label><input type="radio" name="level" value="Intermediate" checked={formData.level === 'Intermediate'} onChange={handleChange} /> Intermediate</label>
            <label><input type="radio" name="level" value="Expert" checked={formData.level === 'Expert'} onChange={handleChange} /> Expert</label>
          </div>

          <div style={{ marginTop: '10px' }}>
            <label>
              <input type="checkbox" name="terms" checked={formData.terms} onChange={handleChange} /> I agree to the terms and conditions
            </label>
          </div>

          <input type="submit" value="Register" />
        </form>

        {message.text && (
          <div className={`${styles.message} ${message.type === 'success' ? styles.success : styles.error}`}>
            {message.text}
          </div>
        )}
      </section>

      <footer className={styles.footer}>
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default RegisterPage;
